-- ARL-KB-008 semantic correction.
-- Aligns the control with privacy-purpose, organisational legal-basis,
-- transparency, retention and rights-handling evidence assessment.

UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"The organisation cannot show why personal data is processed, what the agent does, or how affected people can exercise rights.","customer_symptom":"A user or operator may observe the organisation cannot show why personal data is processed, what the agent does, or how affected people can exercise rights; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious user, compromised dependency, unsafe model behaviour, or operator error can exploit or trigger the condition in the organisation cannot show why personal data is processed, what the agent does, or how affected people can exercise rights, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["agent","model context","tools or downstream systems","customer evidence"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["agents processing personal data or interacting with people"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The test crosses the boundary between agents processing personal data or interacting with people and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If the organisation cannot show why personal data is processed, what the agent does, or how affected people can exercise rights, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-08-05","next_review_due":"2026-11-03","change_triggers":["ARL-KB-008 control or enforcement change","ARL-KB-008 model, prompt, tool, identity, data-source or provider change","ARL-KB-008 bypass, incident or new attack evidence","ARL-KB-008 evidence expiry or material scope change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='60eec8ff9ce6eb730357d77436e2f0db9dc47c95537a1a5806848c3b8068b3e4', updated_at='2026-08-06' WHERE id='ARL-KB-008';
UPDATE risk_knowledge_checks SET objective='Determine whether personal-data processing and human-facing agent use are supported by documented purpose, organisational legal-basis analysis, transparent user information, retention and rights-handling evidence.', method='Identify the personal data and human interactions present in the exact assessed version. Compare the observed processing, purposes, recipients, model or tool destinations, retention and user journey with the organisation''s documented privacy analysis and notices. Verify that the organisation records the purpose and asserted legal basis for applicable processing, provides appropriate transparency about the agent and material data use, defines retention and rights-handling routes, and assigns accountable ownership. ARL verifies the presence, traceability and consistency of this evidence; it does not determine legal sufficiency or provide legal advice. Use synthetic or non-production data and do not exercise rights against real people or third parties during the test.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-008 assessed system, exact version, environment and applicable data/human-interaction scope","ARL-KB-008 observed personal-data categories, purposes, destinations and retention relevant to the assessed path","ARL-KB-008 organisation-approved purpose and asserted legal-basis record for applicable processing","ARL-KB-008 user-facing transparency or notice evidence describing relevant agent/data processing","ARL-KB-008 rights-handling, contact or escalation route and accountable owner where applicable","ARL-KB-008 reviewer identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-008 passes only when applicable personal-data processing and human-facing use observed in the exact assessed version are traceable to documented purposes and the organisation''s asserted legal-basis analysis; relevant user information, retention and rights-handling evidence exists and is consistent with the observed system; accountable ownership is identified; and version-bound evidence supports the conclusion. ARL does not independently certify legal compliance.', fail_condition='ARL-KB-008 fails or requires review when applicable personal-data processing or human-facing agent use lacks a documented purpose or organisational legal-basis record; observed processing materially differs from the documented notice or purpose; relevant retention, transparency, rights-handling or accountable-owner evidence is absent; or the conclusion is unsupported by attributable version-bound evidence.', limitations='This bounded ARL-KB-008 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='329208fe640028673ad75552e789152c4a4e1fab5016f73285c3ca68ba4da489', updated_at='2026-08-06' WHERE entry_id='ARL-KB-008';
UPDATE risk_knowledge_solutions SET control_objective='Make the purpose, organisational legal-basis analysis, transparency, retention and rights handling for applicable personal-data and human-facing agent use explicit, attributable and reviewable.', recommended_remediation='Document the applicable processing purpose and organisation-approved legal-basis analysis; align notices with observed agent and data behaviour; document relevant retention and rights-handling routes; assign accountable privacy ownership; and review the records after material changes to data, purpose, provider or user journey.', default_owner='Privacy counsel and DPO', priority='P1', implementation_principles_json='["ARL-KB-008: enforce the decision outside the model before any material side effect.","ARL-KB-008: grant the minimum identity, data, tool and network scope required for the approved task.","ARL-KB-008: version configuration, preserve rollback, and fail closed when policy, identity or evidence is unavailable."]', monitoring='For ARL-KB-008, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Privacy counsel and DPO on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-008 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-008: “Legal basis, transparency or user notice is unsupported” is no longer reproducible against the exact remediated version.","ARL-KB-008: Authorised in-scope use completes successfully, remains within the documented asset scope for legal basis, transparency or user notice is unsupported, and produces no unintended side effect.","ARL-KB-008: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-008: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='2712f89f7fea6a33bb1b99b7f190ae98eb348e1c96047031d6acffb98c1cd270', updated_at='2026-08-06' WHERE entry_id='ARL-KB-008';
